{
  "a_sentences": [
    {
      "a_text": "Selon l'art. 259b let. a CO, le locataire peut résilier immédiatement le bail si un défaut exclut ou entrave considérablement l'usage de la chose, que le bailleur en a connaissance et qu'il n'y remédie pas dans un délai convenable.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Il appartient à la juridiction cantonale d'apprécier si le défaut est suffisamment grave pour justifier la résiliation.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Un défaut grave exclut l'usage convenu de la chose ou le restreint de telle sorte qu'on ne peut objectivement exiger du locataire qu'il use des locaux, par exemple lorsqu'une activité commerciale ne peut pas être exercée.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "La bailleresse n'a pas remédié dans un délai convenable aux infiltrations d'eau, qui rendaient l'arrière-boutique inutilisable après les dégâts du 8 mai 2021.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme que la résiliation anticipée du 12 juillet 2021 était valable en raison de la gravité du défaut et de l'inaction de la bailleresse.",
      "b_propositions": ["P5", "P6"]
    },
    {
      "a_text": "Le Tribunal fédéral admet le recours des locataires et renvoie la cause à la Cour de justice pour qu'elle détermine la contrepartie financière due pour l'occupation des locaux après l'extinction du bail.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral rejette le grief de la bailleresse relatif à la réduction de loyer, estimant que les critiques s'écartent des constatations cantonales et ne démontrent pas d'arbitraire.",
      "b_propositions": ["P8"]
    }
  ]
}
